const {
  follow,
  unfollow,
  incomingRequests,
  respond,
  followers,
  following,
  removeFollower,
} = require('../controllers/followController');

router.post('/users/:userId/follow', authenticate, authLimiter, follow);
router.delete('/users/:userId/follow', authenticate, authLimiter, unfollow);
